    [Fact]
    public async Task LegacyDemoTrace_PreservesAuditButDoesNotClaimSchemaEvidence()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        var persisted = new AgentTrace { InputHash = "SYNTHETIC", ToolsRequestedJson = "[]", ToolsAllowedJson = "[]", ToolsDeniedJson = "[]", TriageCase = fixture.LinkedCase, Agent = AgentKind.Context,
            Status = AgentStepStatus.Completed, OutputSchemaValid = true, Confidence = 0.41m,
            ModelName = "synthetic-demo", StepNumber = 1 };
        db.Add(persisted);
        await db.SaveChangesAsync();

        var review = await CreateService(db, fixture.DoctorUser.Id, UserType.Doctor).GetCaseReviewAsync(fixture.LinkedCase.Id, CancellationToken.None);

        review.Traces.Single().HasOutput.Should().BeFalse();
        review.Traces.Single().OutputSchemaValid.Should().BeFalse();
        review.Traces.Single().ModelName.Should().Be("synthetic-demo");
        persisted.Status.Should().Be(AgentStepStatus.Completed);
        persisted.Confidence.Should().Be(0.41m);
        persisted.OutputSchemaValid.Should().BeTrue();
    }

    [Theory]
    [InlineData("missing", ApprovalAction.Approve)]
    [InlineData("missing", ApprovalAction.ReviseAndApprove)]
    [InlineData("invalid", ApprovalAction.Approve)]
    [InlineData("nodata", ApprovalAction.Approve)]
    [InlineData("demo", ApprovalAction.Approve)]
    [InlineData("invalidTrace", ApprovalAction.Approve)]
    public async Task Approval_MissingRequiredEvidence_FailsWithoutRelease(string mode, ApprovalAction action)
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        AddEvidence(db, fixture, mode);
        await db.SaveChangesAsync();
        var service = new ClinicalService(db, new StubCurrentUser(fixture.DoctorUser.Id, UserType.Doctor), new StubNotifications(), new ConfigurationBuilder().Build());

        var act = () => service.DecideCaseAsync(fixture.LinkedCase.Id, new ApprovalRequest(action, null, "Please arrange an in-person clinical review."), CancellationToken.None);

        await act.Should().ThrowAsync<ValidationException>();
        fixture.LinkedCase.Status.Should().Be(TriageStatus.PendingDoctorReview);
        (await db.Approvals.CountAsync()).Should().Be(0);
        (await db.CaseAccessGrants.SingleAsync()).RevokedAt.Should().BeNull();
    }

    [Fact]
    public async Task Approval_ValidLowConfidenceEvidenceWithOptionalNoData_PreservesHumanDecision()
    {
        await using var db = NewDb();
        var fixture = await SeedAsync(db);
        await AddGrantAsync(db, fixture, GrantState.Active);
        AddEvidence(db, fixture, "valid");
        fixture.LinkedCase.Status = TriageStatus.LowConfidence;
        db.Add(new AgentTrace { InputHash = "SYNTHETIC", ToolsRequestedJson = "[]", ToolsAllowedJson = "[]", ToolsDeniedJson = "[]", TriageCase = fixture.LinkedCase, Agent = AgentKind.FamilialRisk, Status = AgentStepStatus.NoData, StepNumber = 3 });
        await db.SaveChangesAsync();
        var service = new ClinicalService(db, new StubCurrentUser(fixture.DoctorUser.Id, UserType.Doctor), new StubNotifications(), new ConfigurationBuilder().Build());

        await service.DecideCaseAsync(fixture.LinkedCase.Id, new ApprovalRequest(ApprovalAction.Approve, null, "Please arrange an in-person clinical review."), CancellationToken.None);

        fixture.LinkedCase.Status.Should().Be(TriageStatus.Approved);
        (await db.Approvals.CountAsync()).Should().Be(1);
    }

    private static void AddEvidence(AppDbContext db, Fixture fixture, string mode)
    {
        if (mode == "missing") return;
        fixture.LinkedCase.ContextOutputJson = mode == "invalid" ? "{}" : JsonSerializer.Serialize(new MemberContextOutput("Synthetic context", [], [], [], 0.41m));
        fixture.LinkedCase.AnalysisOutputJson = JsonSerializer.Serialize(new AnalysisFindingsOutput([], [], 0.41m));
        foreach (var agent in new[] { AgentKind.Context, AgentKind.Analysis })
            db.Add(new AgentTrace { InputHash = "SYNTHETIC", ToolsRequestedJson = "[]", ToolsAllowedJson = "[]", ToolsDeniedJson = "[]", TriageCase = fixture.LinkedCase, Agent = agent, StepNumber = agent == AgentKind.Context ? 1 : 2,
                Status = mode == "nodata" && agent == AgentKind.Analysis ? AgentStepStatus.NoData : AgentStepStatus.Completed,
                OutputJson = mode == "invalidTrace" ? "{\"synthetic\":true}" : agent == AgentKind.Context ? fixture.LinkedCase.ContextOutputJson : fixture.LinkedCase.AnalysisOutputJson,
                ModelName = mode == "demo" ? "synthetic-demo" : "synthetic-test", OutputSchemaValid = true, Confidence = 0.41m });
    }

    private sealed class StubNotifications : INotificationService
    {
        public Task<NotificationSubscriptionDto> SubscribeAsync(NotificationSubscriptionRequest request, CancellationToken cancellationToken) => throw new NotSupportedException();
        public Task SendCaseStatusAsync(Guid caseId, TriageStatus status, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task<PagedResult<NotificationDto>> GetInboxAsync(int page, int pageSize, CancellationToken cancellationToken) => throw new NotSupportedException();
    }

    private static AppDbContext NewDb() =>
        new(new DbContextOptionsBuilder<AppDbContext>()
            .UseInMemoryDatabase(Guid.NewGuid().ToString())
            .Options);

    private static TriageService CreateService(AppDbContext db, Guid userId, UserType userType) =>
        new(db, new StubCurrentUser(userId, userType), new StubWorkQueue());

    private static async Task<Fixture> SeedAsync(AppDbContext db)
    {
        var familyUser = new UserAccount
        {
            Email = "synthetic-review-family@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Review Family",
            UserType = UserType.FamilyUser
        };
        var otherFamilyUser = new UserAccount
        {
            Email = "synthetic-review-other@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Other Family",
            UserType = UserType.FamilyUser
        };
        var doctorUser = new UserAccount
        {
            Email = "synthetic-review-doctor@example.invalid",
            PasswordHash = "synthetic-hash",
            DisplayName = "Synthetic Review Doctor",
            UserType = UserType.Doctor
        };
        var family = new Family { Name = "Synthetic Review Family", CreatedByUser = familyUser };
        var otherFamily = new Family { Name = "Synthetic Other Family", CreatedByUser = otherFamilyUser };
        var linkedMember = new Member
        {
            Family = family,
            User = familyUser,
            DisplayName = "Synthetic Linked Member",
            DateOfBirth = new DateOnly(1990, 1, 1),
            Role = FamilyRole.Head
        };
        var otherMember = new Member
        {
            Family = otherFamily,
            User = otherFamilyUser,
            DisplayName = "Synthetic Other Member",
            DateOfBirth = new DateOnly(1992, 2, 2),
            Role = FamilyRole.Head
        };
        var doctor = new Doctor
        {
            User = doctorUser,
            RegistrationNumberHash = "synthetic-registration-hash",
            RegistrationNumberLastFour = "0001",
            VerificationStatus = VerificationStatus.Verified
        };
        var linkedEpisode = new Episode
        {
            Member = linkedMember,
            SymptomsJson = "[\"synthetic_persistent_cough\",\"synthetic_fatigue\"]",
            DurationDays = 4,
            Severity = 3,
            Notes = "Synthetic linked episode note."
        };
        var otherMemberEpisode = new Episode
        {
            Member = otherMember,
            SymptomsJson = "[\"synthetic_unrelated_symptom\"]",
            DurationDays = 9,
            Severity = 1,
            Notes = "Synthetic unrelated episode note."
        };
        var linkedCase = new TriageCase
        {
            Episode = linkedEpisode,
            Member = linkedMember,
            Status = TriageStatus.PendingDoctorReview,
            Priority = TriagePriority.Priority
        };
        var otherMemberCase = new TriageCase
        {
            Episode = otherMemberEpisode,
            Member = otherMember,
            Status = TriageStatus.PendingDoctorReview,
            Priority = TriagePriority.Routine
        };

        db.AddRange(
            familyUser,
            otherFamilyUser,
            doctorUser,
            family,
            otherFamily,
            linkedMember,
            otherMember,
            doctor,
            linkedEpisode,
            otherMemberEpisode,
            linkedCase,
            otherMemberCase);
        await db.SaveChangesAsync();

        return new Fixture(
            familyUser,
            doctorUser,
            doctor,
            linkedMember,
            linkedEpisode,
            linkedCase,
            otherMemberEpisode,
            otherMemberCase);
    }

    private static async Task AddGrantAsync(AppDbContext db, Fixture fixture, GrantState grantState)
    {
        if (grantState == GrantState.None)
        {
            return;
        }

        var now = DateTimeOffset.UtcNow;
        db.CaseAccessGrants.Add(new CaseAccessGrant
        {
            TriageCase = fixture.LinkedCase,
            Doctor = fixture.Doctor,
            ExpiresAt = grantState == GrantState.Expired ? now.AddMinutes(-1) : now.AddHours(1),
            RevokedAt = grantState == GrantState.Revoked ? now.AddMinutes(-1) : null,
            Reason = "SYNTHETIC_REVIEW_TEST"
        });
        await db.SaveChangesAsync();
    }

    private sealed record Fixture(
        UserAccount FamilyUser,
        UserAccount DoctorUser,
        Doctor Doctor,
        Member LinkedMember,
        Episode LinkedEpisode,
        TriageCase LinkedCase,
        Episode OtherMemberEpisode,
        TriageCase OtherMemberCase);

    private sealed class StubCurrentUser(Guid userId, UserType userType) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => userType;
    }

    private sealed class StubWorkQueue : ITriageWorkQueue
    {
        public ValueTask QueueAsync(Guid caseId, CancellationToken cancellationToken) => ValueTask.CompletedTask;
        public ValueTask<Guid> DequeueAsync(CancellationToken cancellationToken) => ValueTask.FromResult(Guid.Empty);
    }

    public enum GrantState
    {
        None,
        Active,
        Expired,
        Revoked
    }
}
